import React, { useState } from 'react';
import { cn } from '../../utils/cn';

export type TooltipItem = {
  id: number | string;
  name: string;
  designation?: string;
  image: string;
  badge?: string;
};

export type AnimatedTooltipProps = {
  items: TooltipItem[];
  className?: string;
  size?: 'sm' | 'md' | 'lg';
  overlap?: boolean;
};

export const AnimatedTooltip = ({
  items,
  className,
  size = 'md',
  overlap = true,
}: AnimatedTooltipProps) => {
  const [hoveredId, setHoveredId] = useState<number | string | null>(null);
  const [xOffset, setXOffset] = useState(0);

  const sizeClasses = {
    sm: 'w-8 h-8 text-xs',
    md: 'w-11 h-11 text-sm',
    lg: 'w-14 h-14 text-base',
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const halfWidth = e.currentTarget.offsetWidth / 2;
    setXOffset(e.nativeEvent.offsetX - halfWidth);
  };

  return (
    <div className={cn('flex flex-row items-center justify-center py-4', className)}>
      {items.map((item) => {
        const isHovered = hoveredId === item.id;
        return (
          <div
            key={item.id}
            className={cn(
              'relative group cursor-pointer transition-all duration-200',
              overlap && '-mr-3.5 hover:mr-1'
            )}
            onMouseEnter={() => setHoveredId(item.id)}
            onMouseLeave={() => {
              setHoveredId(null);
              setXOffset(0);
            }}
            onMouseMove={handleMouseMove}
          >
            {isHovered && (
              <div
                style={{
                  transform: `translateX(${xOffset * 0.45}px) rotate(${xOffset * 0.08}deg)`,
                }}
                className="absolute -top-14 left-1/2 -translate-x-1/2 z-50 flex flex-col items-center justify-center whitespace-nowrap pointer-events-none transition-transform duration-75 ease-out"
              >
                <div className="flex flex-col items-center justify-center rounded-xl bg-neutral-900/95 dark:bg-neutral-100/95 text-white dark:text-neutral-900 px-3.5 py-1.5 shadow-2xl backdrop-blur-md border border-white/10 dark:border-black/10">
                  <div className="flex items-center gap-1.5">
                    <span className="text-xs font-bold leading-tight">{item.name}</span>
                    {item.badge && (
                      <span className="rounded-full bg-[var(--patiya-color-primary)] px-1.5 py-0.2 text-[9px] font-semibold text-white">
                        {item.badge}
                      </span>
                    )}
                  </div>
                  {item.designation && (
                    <span className="text-[10px] text-neutral-300 dark:text-neutral-600 font-medium leading-tight mt-0.5">
                      {item.designation}
                    </span>
                  )}
                </div>
                <div className="w-2.5 h-2.5 bg-neutral-900/95 dark:bg-neutral-100/95 rotate-45 -mt-1 border-r border-b border-white/10 dark:border-black/10" />
              </div>
            )}
            <img
              src={item.image}
              alt={item.name}
              className={cn(
                'object-cover rounded-full border-2 border-[var(--patiya-color-background)] shadow-md transition-all duration-300 group-hover:scale-125 group-hover:z-30 relative group-hover:border-[var(--patiya-color-primary)]',
                sizeClasses[size],
                isHovered ? 'z-30 shadow-xl' : 'z-10'
              )}
            />
          </div>
        );
      })}
    </div>
  );
};

import React, { forwardRef, useState } from "react";
import { cn } from "../../utils/cn";

export type ArtifactStatus = "idle" | "generating" | "ready" | "error";
export type ArtifactType = "code" | "react" | "html" | "svg" | "markdown";

export type ArtifactVersion = {
  version: number;
  label?: string;
  code: string;
};

export type ArtifactCanvasProps = React.HTMLAttributes<HTMLDivElement> & {
  title: string;
  type?: ArtifactType;
  language?: string;
  code: string;
  preview?: React.ReactNode;
  status?: ArtifactStatus;
  versions?: ArtifactVersion[];
  activeVersion?: number;
  onVersionChange?: (version: number) => void;
  onCopy?: () => void;
  onDownload?: () => void;
};

export const ArtifactCanvas = forwardRef<HTMLDivElement, ArtifactCanvasProps>(
  (
    {
      className,
      title,
      type = "code",
      language = "typescript",
      code,
      preview,
      status = "ready",
      versions,
      activeVersion,
      onVersionChange,
      onCopy,
      onDownload,
      ...props
    },
    ref
  ) => {
    const [tab, setTab] = useState<"preview" | "code">(
      preview ? "preview" : "code"
    );
    const [copied, setCopied] = useState(false);
    const [isFullscreen, setIsFullscreen] = useState(false);

    const handleCopy = () => {
      navigator.clipboard.writeText(code);
      setCopied(true);
      onCopy?.();
      setTimeout(() => setCopied(false), 2000);
    };

    const handleDownload = () => {
      if (onDownload) {
        onDownload();
        return;
      }
      const ext =
        type === "react"
          ? "tsx"
          : type === "html"
            ? "html"
            : type === "svg"
              ? "svg"
              : type === "markdown"
                ? "md"
                : "txt";
      const blob = new Blob([code], { type: "text/plain;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${title.toLowerCase().replace(/\s+/g, "-")}.${ext}`;
      a.click();
      URL.revokeObjectURL(url);
    };

    return (
      <div
        ref={ref}
        className={cn(
          "w-full rounded-2xl border border-[var(--patiya-color-border)] bg-[var(--patiya-color-card)] overflow-hidden transition-all duration-200 flex flex-col",
          isFullscreen
            ? "fixed inset-4 z-50 shadow-2xl h-[calc(100vh-2rem)]"
            : "relative max-w-3xl",
          status === "generating" && "ring-2 ring-[var(--patiya-color-primary)]/40 ring-offset-2 ring-offset-[var(--patiya-color-background)]",
          className
        )}
        {...props}
      >
        <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--patiya-color-border)] bg-[var(--patiya-color-muted)]/30 backdrop-blur-sm">
          <div className="flex items-center gap-2.5 min-w-0">
            <div className="w-7 h-7 rounded-lg bg-[var(--patiya-color-primary)]/10 text-[var(--patiya-color-primary)] flex items-center justify-center shrink-0 border border-[var(--patiya-color-primary)]/20">
              {type === "react" || type === "html" ? (
                <svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <polyline points="16 18 22 12 16 6" />
                  <polyline points="8 6 2 12 8 18" />
                </svg>
              ) : type === "svg" ? (
                <svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <circle cx="12" cy="12" r="10" />
                  <polygon points="12 8 8 12 12 16 16 12 12 8" />
                </svg>
              ) : (
                <svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                  <polyline points="14 2 14 8 20 8" />
                </svg>
              )}
            </div>

            <div className="flex flex-col min-w-0">
              <div className="flex items-center gap-2">
                <span className="text-xs font-semibold text-[var(--patiya-color-foreground)] truncate">
                  {title}
                </span>
                {status === "generating" && (
                  <span className="flex items-center gap-1 text-[10px] font-mono text-[var(--patiya-color-primary)]">
                    <span className="w-1.5 h-1.5 rounded-full bg-[var(--patiya-color-primary)] animate-pulse" />
                    Generating...
                  </span>
                )}
              </div>
              <span className="text-[10px] font-mono text-[var(--patiya-color-muted-foreground)]">
                {language}
              </span>
            </div>
          </div>

          <div className="flex items-center gap-1.5">
            {versions && versions.length > 1 && (
              <div className="flex items-center gap-1 mr-2 px-1.5 py-0.5 rounded-lg border border-[var(--patiya-color-border)] bg-[var(--patiya-color-background)]">
                {versions.map((v) => (
                  <button
                    key={v.version}
                    onClick={() => onVersionChange?.(v.version)}
                    className={cn(
                      "text-[10px] font-mono px-1.5 py-0.5 rounded transition-colors",
                      activeVersion === v.version
                        ? "bg-[var(--patiya-color-primary)] text-[var(--patiya-color-primary-foreground)] font-bold"
                        : "text-[var(--patiya-color-muted-foreground)] hover:text-[var(--patiya-color-foreground)]"
                    )}
                  >
                    v{v.version}
                  </button>
                ))}
              </div>
            )}

            {preview && (
              <div className="flex items-center p-0.5 rounded-lg bg-[var(--patiya-color-muted)] border border-[var(--patiya-color-border)]">
                <button
                  type="button"
                  onClick={() => setTab("preview")}
                  className={cn(
                    "px-2.5 py-1 text-xs font-medium rounded-md transition-all",
                    tab === "preview"
                      ? "bg-[var(--patiya-color-background)] text-[var(--patiya-color-foreground)] shadow-xs"
                      : "text-[var(--patiya-color-muted-foreground)] hover:text-[var(--patiya-color-foreground)]"
                  )}
                >
                  Preview
                </button>
                <button
                  type="button"
                  onClick={() => setTab("code")}
                  className={cn(
                    "px-2.5 py-1 text-xs font-medium rounded-md transition-all",
                    tab === "code"
                      ? "bg-[var(--patiya-color-background)] text-[var(--patiya-color-foreground)] shadow-xs"
                      : "text-[var(--patiya-color-muted-foreground)] hover:text-[var(--patiya-color-foreground)]"
                  )}
                >
                  Code
                </button>
              </div>
            )}

            <button
              type="button"
              onClick={handleCopy}
              className="p-1.5 rounded-lg text-[var(--patiya-color-muted-foreground)] hover:text-[var(--patiya-color-foreground)] hover:bg-[var(--patiya-color-muted)] transition-colors"
              title="Copy code"
            >
              {copied ? (
                <svg className="w-3.5 h-3.5 text-emerald-500" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                  <polyline points="20 6 9 17 4 12" />
                </svg>
              ) : (
                <svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <rect x="9" y="9" width="13" height="13" rx="2" ry="2" />
                  <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
                </svg>
              )}
            </button>

            <button
              type="button"
              onClick={handleDownload}
              className="p-1.5 rounded-lg text-[var(--patiya-color-muted-foreground)] hover:text-[var(--patiya-color-foreground)] hover:bg-[var(--patiya-color-muted)] transition-colors"
              title="Download file"
            >
              <svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
                <polyline points="7 10 12 15 17 10" />
                <line x1="12" y1="15" x2="12" y2="3" />
              </svg>
            </button>

            <button
              type="button"
              onClick={() => setIsFullscreen(!isFullscreen)}
              className="p-1.5 rounded-lg text-[var(--patiya-color-muted-foreground)] hover:text-[var(--patiya-color-foreground)] hover:bg-[var(--patiya-color-muted)] transition-colors"
              title={isFullscreen ? "Exit fullscreen" : "Fullscreen"}
            >
              {isFullscreen ? (
                <svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <polyline points="4 14 10 14 10 20" />
                  <polyline points="20 10 14 10 14 4" />
                  <line x1="14" y1="10" x2="21" y2="3" />
                  <line x1="3" y1="21" x2="10" y2="14" />
                </svg>
              ) : (
                <svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <polyline points="15 3 21 3 21 9" />
                  <polyline points="9 21 3 21 3 15" />
                  <line x1="21" y1="3" x2="14" y2="10" />
                  <line x1="3" y1="21" x2="10" y2="14" />
                </svg>
              )}
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-auto min-h-[220px]">
          {tab === "preview" && preview ? (
            <div className="p-6 h-full flex items-center justify-center bg-[var(--patiya-color-background)]">
              {preview}
            </div>
          ) : (
            <pre className="p-4 text-xs font-mono text-[var(--patiya-color-foreground)] leading-relaxed overflow-x-auto selection:bg-[var(--patiya-color-primary)]/20">
              <code>{code}</code>
            </pre>
          )}
        </div>
      </div>
    );
  }
);
ArtifactCanvas.displayName = "ArtifactCanvas";

