            <span className="px-2 py-0.5 rounded-full text-[11px] font-mono font-semibold bg-[var(--patiya-color-muted)] text-[var(--patiya-color-muted-foreground)]">
              {items.length} {items.length === 1 ? 'item' : 'items'}
