export const Dock = React.forwardRef<HTMLDivElement, DockProps>(
  (
    {
      className,
      children,
      magnification = 64,
      distance = 140,
      direction = 'bottom',
      baseSize = 40,
      ...props
    },
    ref
  ) => {
    const [mouseX, setMouseX] = useState<number | null>(null);

    const handleMouseMove = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
      setMouseX(e.clientX);
    }, []);

    const handleMouseLeave = useCallback(() => {
      setMouseX(null);
    }, []);

    const directionClasses: Record<DockDirection, string> = {
      top: 'items-start',
      middle: 'items-center',
      bottom: 'items-end',
    };

    return (
      <DockContext.Provider value={{ mouseX, magnification, distance, baseSize }}>
        <div
          ref={ref}
          onMouseMove={handleMouseMove}
          onMouseLeave={handleMouseLeave}
          className={cn(
            'inline-flex gap-3 p-3 rounded-2xl bg-black/5 dark:bg-neutral-900/80 border border-black/10 dark:border-white/15 shadow-xl backdrop-blur-2xl transition-all',
            directionClasses[direction],
            className
          )}
          {...props}
        >
          {children}
        </div>
      </DockContext.Provider>
    );
  }
);
Dock.displayName = 'Dock';

export type DockItemProps = React.HTMLAttributes<HTMLDivElement> & {
  magnification?: number;
  distance?: number;
  baseSize?: number;
  label?: string;
  active?: boolean;
};

export const DockItem = React.forwardRef<HTMLDivElement, DockItemProps>(
  (
    {
      className,
      children,
      magnification: propMag,
      distance: propDist,
      baseSize: propBase,
      label,
      active = false,
      ...props
    },
    ref
  ) => {
    const context = useContext(DockContext);
    const itemRef = useRef<HTMLDivElement>(null);

    const base = propBase ?? context.baseSize ?? 40;
    const mag = propMag ?? context.magnification ?? 64;
    const dist = propDist ?? context.distance ?? 140;
    const mouseX = context.mouseX;

    const [size, setSize] = useState(base);

    useEffect(() => {
      if (!itemRef.current || mouseX === null) {
        setSize(base);
        return;
      }

      const rect = itemRef.current.getBoundingClientRect();
      const itemCenterX = rect.left + rect.width / 2;
      const d = Math.abs(mouseX - itemCenterX);

      if (d < dist) {
        const factor = Math.cos((d / dist) * (Math.PI / 2));
        const newSize = base + (mag - base) * factor;
        setSize(Math.round(newSize * 10) / 10);
      } else {
        setSize(base);
      }
    }, [mouseX, base, mag, dist]);

    return (
      <div className="relative group inline-flex flex-col items-center">
        {label && (
          <div className="absolute -top-8 px-2 py-0.5 rounded-md text-[11px] font-medium bg-[var(--patiya-color-foreground)] text-[var(--patiya-color-background)] shadow-md pointer-events-none transition-all duration-150 opacity-0 -translate-y-1 group-hover:opacity-100 group-hover:translate-y-0 whitespace-nowrap z-30">
            {label}
          </div>
        )}
        <div
          ref={(node) => {
            if (typeof ref === 'function') ref(node);
            else if (ref) ref.current = node;
            (itemRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
          }}
          style={{ width: `${size}px`, height: `${size}px` }}
          className={cn(
            'flex items-center justify-center rounded-2xl bg-white dark:bg-neutral-800 text-[var(--patiya-color-foreground)] border border-black/10 dark:border-white/15 shadow-sm hover:shadow-md hover:bg-neutral-50 dark:hover:bg-neutral-700 transition-all duration-75 ease-out cursor-pointer select-none active:scale-95',
            className
          )}
          {...props}
        >
          {children}
        </div>
        {active && (
          <span className="w-1 h-1 rounded-full bg-[var(--patiya-color-primary)] mt-1 absolute -bottom-2" />
        )}
      </div>
    );
  }
);
DockItem.displayName = 'DockItem';

import React from 'react';
import {
  useFloating,
  useDismiss,
  useRole,
  useInteractions,
  FloatingFocusManager,
  FloatingOverlay,
  FloatingPortal,
  useTransitionStyles
} from '@floating-ui/react';
import { cn } from '../../utils/cn';
import { Box } from '../Layout/Box';

export type DrawerProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  children: React.ReactNode;
  side?: 'right' | 'left' | 'top' | 'bottom';
  position?: 'right' | 'left' | 'top' | 'bottom';
  size?: 'sm' | 'md' | 'lg' | 'xl' | 'full' | string;
  className?: string;
  overlayClassName?: string;
};

export function Drawer({
  open,
  onOpenChange,
  children,
  side,
  position,
  size,
  className,
  overlayClassName,
}: DrawerProps) {
  const actualSide = side || position || 'right';
  const { refs, context } = useFloating({
    open,
    onOpenChange,
  });

  const dismiss = useDismiss(context, { outsidePressEvent: 'mousedown' });
  const role = useRole(context);

  const { getFloatingProps } = useInteractions([dismiss, role]);

  const getSlideTransform = (s: string) => {
    switch (s) {
      case 'right': return 'translate3d(100%, 0, 0)';
      case 'left': return 'translate3d(-100%, 0, 0)';
      case 'top': return 'translate3d(0, -100%, 0)';
      case 'bottom': return 'translate3d(0, 100%, 0)';
      default: return 'translate3d(100%, 0, 0)';
    }
  };

  const { isMounted, styles: panelStyles } = useTransitionStyles(context, {
    duration: 320,
    initial: {
      transform: getSlideTransform(actualSide),
    },
    open: {
      transform: 'translate3d(0, 0, 0)',
    },
    close: {
      transform: getSlideTransform(actualSide),
    },
    common: {
      transitionProperty: 'transform',
      transitionTimingFunction: 'cubic-bezier(0.32, 0.72, 0, 1)',
    },
  });

  const { styles: overlayStyles } = useTransitionStyles(context, {
    duration: 320,
    initial: { opacity: 0 },
    open: { opacity: 1 },
    close: { opacity: 0 },
    common: {
      transitionProperty: 'opacity',
      transitionTimingFunction: 'ease-out',
    },
  });

  const sideClasses = {
    right: 'inset-y-0 right-0 h-full w-full max-w-sm border-l sm:max-w-md',
    left: 'inset-y-0 left-0 h-full w-full max-w-sm border-r sm:max-w-md',
    top: 'inset-x-0 top-0 w-full max-h-[85vh] border-b shadow-2xl',
    bottom: 'inset-x-0 bottom-0 w-full max-h-[85vh] border-t rounded-t-2xl shadow-2xl',
  };

  const sizeClasses: Record<string, string> = {
    sm: 'max-w-sm',
    md: 'max-w-md',
    lg: 'max-w-lg',
    xl: 'max-w-xl',
    full: 'max-w-full',
  };

  return (
    <>
      {isMounted && (
        <FloatingPortal>
          <FloatingOverlay
            style={{ ...overlayStyles, overflow: 'hidden' }}
            className={cn(
              "z-50 bg-black/60 backdrop-blur-sm overflow-hidden",
              overlayClassName
            )}
            lockScroll
          >
            <FloatingFocusManager context={context} initialFocus={-1}>
              <Box
                ref={refs.setFloating}
                {...getFloatingProps()}
                tabIndex={-1}
                style={{ ...panelStyles, willChange: 'transform' }}
                className={cn(
                  "absolute z-50 bg-[var(--patiya-color-background)] p-6 shadow-2xl border-[var(--patiya-color-border)] outline-none flex flex-col overflow-y-auto transform-gpu",
                  sideClasses[actualSide],
                  size && sizeClasses[size],
                  className
                )}
              >
                {children}
              </Box>
            </FloatingFocusManager>
          </FloatingOverlay>
        </FloatingPortal>
      )}
    </>
  );
}

