import React, { useRef, useState, useCallback } from 'react';
import { cn } from '../../utils/cn';

export type HoloFoil = 'rainbow' | 'cosmic' | 'gold' | 'neon' | 'silver';

export type HoloCardProps = React.HTMLAttributes<HTMLDivElement> & {
  foil?: HoloFoil;
  glare?: boolean;
  glareOpacity?: number;
  maxTilt?: number;
  perspective?: number;
  sparkles?: boolean;
};

export const HoloCard = React.forwardRef<HTMLDivElement, HoloCardProps>(
  (
    {
      className,
      foil = 'rainbow',
      glare = true,
      glareOpacity = 0.5,
      maxTilt = 18,
      perspective = 1000,
      sparkles = true,
      children,
      onMouseMove,
      onMouseLeave,
      ...props
    },
    forwardedRef
  ) => {
    const internalRef = useRef<HTMLDivElement>(null);
    const cardRef = (forwardedRef as React.RefObject<HTMLDivElement>) || internalRef;

    const [tilt, setTilt] = useState({ x: 0, y: 0 });
    const [glarePos, setGlarePos] = useState({ x: 50, y: 50, opacity: 0 });
    const [foilAngle, setFoilAngle] = useState(135);
    const [isHovered, setIsHovered] = useState(false);

    const handleMouseMove = useCallback(
      (e: React.MouseEvent<HTMLDivElement>) => {
        if (!cardRef.current) return;
        const rect = cardRef.current.getBoundingClientRect();
        const clientX = e.clientX - rect.left;
        const clientY = e.clientY - rect.top;

        const xPct = (clientX / rect.width) * 100;
        const yPct = (clientY / rect.height) * 100;

        const tiltX = ((yPct - 50) / 50) * -maxTilt;
        const tiltY = ((xPct - 50) / 50) * maxTilt;

        const rad = Math.atan2(yPct - 50, xPct - 50);
        const deg = (rad * 180) / Math.PI + 90;

        setTilt({ x: tiltX, y: tiltY });
        setGlarePos({ x: xPct, y: yPct, opacity: glareOpacity });
        setFoilAngle(deg);
        setIsHovered(true);

        onMouseMove?.(e);
      },
      [cardRef, glareOpacity, maxTilt, onMouseMove]
    );

    const handleMouseLeave = useCallback(
      (e: React.MouseEvent<HTMLDivElement>) => {
        setTilt({ x: 0, y: 0 });
        setGlarePos((prev) => ({ ...prev, opacity: 0 }));
        setIsHovered(false);
        onMouseLeave?.(e);
      },
      [onMouseLeave]
    );

    const foilGradients: Record<HoloFoil, string> = {
      rainbow:
        'linear-gradient(var(--foil-angle, 135deg), rgba(255,0,128,0.3) 0%, rgba(255,165,0,0.3) 20%, rgba(255,255,0,0.3) 40%, rgba(0,255,128,0.3) 60%, rgba(0,191,255,0.3) 80%, rgba(138,43,226,0.3) 100%)',
      cosmic:
        'linear-gradient(var(--foil-angle, 135deg), rgba(168,85,247,0.35) 0%, rgba(59,130,246,0.35) 35%, rgba(236,72,153,0.35) 70%, rgba(99,102,241,0.35) 100%)',
      gold:
        'linear-gradient(var(--foil-angle, 135deg), rgba(245,158,11,0.4) 0%, rgba(253,230,138,0.5) 30%, rgba(217,119,6,0.4) 60%, rgba(251,191,36,0.5) 100%)',
      neon:
        'linear-gradient(var(--foil-angle, 135deg), rgba(6,182,212,0.4) 0%, rgba(16,185,129,0.35) 33%, rgba(236,72,153,0.4) 66%, rgba(139,92,246,0.4) 100%)',
      silver:
        'linear-gradient(var(--foil-angle, 135deg), rgba(255,255,255,0.45) 0%, rgba(203,213,225,0.2) 25%, rgba(255,255,255,0.5) 50%, rgba(148,163,184,0.2) 75%, rgba(255,255,255,0.45) 100%)',
    };

    return (
      <div
        style={{ perspective: `${perspective}px` }}
        className="relative flex justify-center w-full"
      >
        <div
          ref={cardRef}
          onMouseMove={handleMouseMove}
          onMouseLeave={handleMouseLeave}
          style={
            {
              '--foil-angle': `${foilAngle}deg`,
              transform: `rotateX(${tilt.x}deg) rotateY(${tilt.y}deg)`,
              transformStyle: 'preserve-3d',
              transition: isHovered ? 'transform 0.08s ease-out' : 'transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1)',
            } as React.CSSProperties
          }
          className={cn(
            'group relative overflow-hidden mx-auto rounded-2xl border border-[var(--patiya-color-border)]/80 bg-[var(--patiya-color-card)]/90 backdrop-blur-xl shadow-xl transition-shadow duration-300 hover:shadow-2xl hover:border-[var(--patiya-color-primary)]/40',
            className
          )}
          {...props}
        >
          <div
            aria-hidden="true"
            style={{
              background: foilGradients[foil],
              opacity: isHovered ? 1 : 0,
              transition: 'opacity 0.4s ease',
              mixBlendMode: 'color-dodge',
            }}
            className="pointer-events-none absolute inset-0 z-10 transition-opacity duration-300"
          />

          {glare && (
            <div
              aria-hidden="true"
              style={{
                background: `radial-gradient(circle at ${glarePos.x}% ${glarePos.y}%, rgba(255, 255, 255, 0.65) 0%, rgba(255, 255, 255, 0) 65%)`,
                opacity: glarePos.opacity,
                transition: isHovered ? 'opacity 0.15s ease' : 'opacity 0.4s ease',
                mixBlendMode: 'overlay',
              }}
              className="pointer-events-none absolute inset-0 z-20"
            />
          )}

          {sparkles && isHovered && (
            <div
              aria-hidden="true"
              style={{
                backgroundImage:
                  'radial-gradient(circle at 20% 30%, rgba(255,255,255,0.8) 1px, transparent 1px), radial-gradient(circle at 80% 40%, rgba(255,255,255,0.7) 1.5px, transparent 1.5px), radial-gradient(circle at 40% 80%, rgba(255,255,255,0.8) 1px, transparent 1px), radial-gradient(circle at 70% 85%, rgba(255,255,255,0.6) 1.5px, transparent 1.5px)',
                backgroundSize: '80px 80px',
              }}
              className="pointer-events-none absolute inset-0 z-15 opacity-40 animate-pulse"
            />
          )}

          <div
            style={{ transform: 'translateZ(26px)', transformStyle: 'preserve-3d' }}
            className="relative z-30 h-full w-full"
          >
            {children}
          </div>
        </div>
      </div>
    );
  }
);

HoloCard.displayName = 'HoloCard';

import React, { useState, useEffect } from 'react';
import { cn } from '../../utils/cn';
import { createPortal } from 'react-dom';

export interface ImageZoomProps extends React.ImgHTMLAttributes<HTMLImageElement> {
  zoomSrc?: string;
  isOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  onNext?: () => void;
  onPrev?: () => void;
}

export const ImageZoom = React.forwardRef<HTMLImageElement, ImageZoomProps>(
  ({ src, zoomSrc, alt, className, isOpen, onOpenChange, onNext, onPrev, ...props }, ref) => {
    const [internalIsZoomed, setInternalIsZoomed] = useState(false);
    const [mounted, setMounted] = useState(false);

    const isZoomed = isOpen !== undefined ? isOpen : internalIsZoomed;

    const handleZoomChange = (newZoom: boolean) => {
      setInternalIsZoomed(newZoom);
      onOpenChange?.(newZoom);
    };

    useEffect(() => {
      setMounted(true);

      const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') handleZoomChange(false);
        if (e.key === 'ArrowRight' && onNext) onNext();
        if (e.key === 'ArrowLeft' && onPrev) onPrev();
      };

      if (isZoomed) {
        document.body.style.overflow = 'hidden';
        window.addEventListener('keydown', handleKeyDown);
      } else {
        document.body.style.overflow = 'unset';
      }

      return () => {
        document.body.style.overflow = 'unset';
        window.removeEventListener('keydown', handleKeyDown);
      };
    }, [isZoomed, onNext, onPrev]);

    return (
      <>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          ref={ref}
          src={src}
          alt={alt}
          className={cn(
            'cursor-zoom-in transition-all duration-300 hover:opacity-90',
            className
          )}
          onClick={() => handleZoomChange(true)}
          {...props}
        />

        {mounted && isZoomed && createPortal(
          <div 
            className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-sm cursor-zoom-out animate-in fade-in duration-300"
            onClick={() => handleZoomChange(false)}
          >
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={zoomSrc || src}
              alt={alt}
              className="max-w-[90vw] max-h-[90vh] object-contain shadow-2xl animate-in zoom-in-95 duration-300 cursor-default"
              onClick={(e) => e.stopPropagation()}
            />

            <button
              onClick={(e) => { e.stopPropagation(); handleZoomChange(false); }}
              className="absolute top-4 right-4 z-10 w-10 h-10 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center text-white transition-colors cursor-pointer"
              aria-label="Close zoom"
            >
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>

            {onPrev && (
              <button
                onClick={(e) => { e.stopPropagation(); onPrev(); }}
                className="absolute left-4 top-1/2 -translate-y-1/2 z-10 w-12 h-12 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center text-white transition-colors cursor-pointer"
                aria-label="Previous image"
              >
                <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
                </svg>
              </button>
            )}

            {onNext && (
              <button
                onClick={(e) => { e.stopPropagation(); onNext(); }}
                className="absolute right-4 top-1/2 -translate-y-1/2 z-10 w-12 h-12 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center text-white transition-colors cursor-pointer"
                aria-label="Next image"
              >
                <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                </svg>
              </button>
            )}
          </div>,
          document.body
        )}
      </>
    );
  }
);

ImageZoom.displayName = 'ImageZoom';

import React, { forwardRef, useState, useRef, useImperativeHandle } from 'react';
import { cn } from '../../utils/cn';
import { PatiyaSize } from '../../types/common';
import { Box } from '../Layout/Box';

export type InputProps = Omit<React.InputHTMLAttributes<HTMLInputElement>, 'size'> & {
  inputSize?: PatiyaSize;
  variant?: 'outline' | 'filled' | 'soft';
  invalid?: boolean;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
  showPasswordToggle?: boolean;
  eyeIcon?: React.ReactNode;
  eyeOffIcon?: React.ReactNode;
  clearable?: boolean;
  onClear?: () => void;
};

const DefaultEyeIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z" />
    <circle cx="12" cy="12" r="3" />
  </svg>
);

const DefaultEyeOffIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M9.88 9.88a3 3 0 1 0 4.24 4.24" />
    <path d="M10.73 5.08A10.43 10.43 0 0 1 12 5c7 0 10 7 10 7a13.16 13.16 0 0 1-1.67 2.68" />
    <path d="M6.61 6.61A13.526 13.526 0 0 0 2 12s3 7 10 7a9.74 9.74 0 0 0 5.39-1.61" />
    <line x1="2" x2="22" y1="2" y2="22" />
  </svg>
);

export const Input = forwardRef<HTMLInputElement, InputProps>(
  (
    {
      className,
      inputSize = 'md',
      variant = 'outline',
      invalid = false,
      leftIcon,
      rightIcon,
      disabled,
      type = 'text',
      showPasswordToggle = false,
      eyeIcon,
      eyeOffIcon,
      clearable = false,
      onClear,
      value,
      defaultValue,
      onChange,
      ...props
    },
    ref
  ) => {
    const internalInputRef = useRef<HTMLInputElement>(null);
    useImperativeHandle(ref, () => internalInputRef.current as HTMLInputElement);

    const [showPassword, setShowPassword] = useState(false);
    const [internalValue, setInternalValue] = useState(defaultValue ?? '');

    const isControlled = value !== undefined;
    const currentVal = isControlled ? value : internalValue;
    const hasValue = currentVal !== undefined && currentVal !== null && currentVal !== '';

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (!isControlled) {
        setInternalValue(e.target.value);
      }
      onChange?.(e);
    };

    const handleClear = () => {
      if (!isControlled) {
        setInternalValue('');
      }
      if (internalInputRef.current) {
        internalInputRef.current.value = '';
        const syntheticEvent = new Event('input', { bubbles: true });
        internalInputRef.current.dispatchEvent(syntheticEvent);
        internalInputRef.current.focus();
      }
      onClear?.();
    };

    const isPassword = type === 'password';
    const computedType = isPassword && showPassword ? 'text' : type;

    let computedRightIcon = rightIcon;
    if (!computedRightIcon) {
      if (isPassword && showPasswordToggle) {
        computedRightIcon = (
          <button
            type="button"
            disabled={disabled}
            onClick={() => setShowPassword((prev) => !prev)}
            aria-label={showPassword ? 'Hide password' : 'Show password'}
            className="cursor-pointer text-[var(--patiya-color-muted-foreground)] hover:text-[var(--patiya-color-foreground)] transition-colors"
          >
            {showPassword ? (eyeOffIcon || <DefaultEyeOffIcon />) : (eyeIcon || <DefaultEyeIcon />)}
          </button>
        );
      } else if (clearable && hasValue) {
        computedRightIcon = (
          <button
            type="button"
            disabled={disabled}
            onClick={handleClear}
            aria-label="Clear input"
            className="cursor-pointer text-xs px-1 text-[var(--patiya-color-muted-foreground)] hover:text-[var(--patiya-color-foreground)] transition-colors"
          >
            ✕
          </button>
        );
      }
    }

    const sizeClasses: Record<PatiyaSize, string> = {
      xs: 'h-7 text-xs px-2',
      sm: 'h-8 text-sm px-3',
      md: 'h-10 text-base px-4',
      lg: 'h-12 text-lg px-4',
      xl: 'h-14 text-xl px-5',
    };

    const variantClasses = {
      outline: 'bg-transparent border border-[var(--patiya-color-border)] focus:border-[var(--patiya-color-primary)] shadow-[var(--patiya-shadow-sm)]',
      filled: 'bg-[var(--patiya-color-muted)] border border-transparent focus:bg-transparent focus:border-[var(--patiya-color-primary)]',
      soft: 'bg-[var(--patiya-color-primary)]/5 border border-transparent focus:bg-transparent focus:border-[var(--patiya-color-primary)]',
    };

    const inputClassName = cn(
      'flex w-full rounded-md transition-all duration-200 outline-none',
      'text-[var(--patiya-color-foreground)] placeholder:text-(--patiya-color-muted-foreground)',
      'focus:ring-4 focus:ring-[var(--patiya-color-primary)]/10',
      'disabled:cursor-not-allowed disabled:opacity-50',
      sizeClasses[inputSize],
      variantClasses[variant],
      invalid && 'border-[var(--patiya-color-destructive)] focus:border-[var(--patiya-color-destructive)] focus:ring-[var(--patiya-color-destructive)]/10',
      leftIcon && 'pl-10',
      computedRightIcon && 'pr-10',
      !leftIcon && !computedRightIcon && className
    );

    if (leftIcon || computedRightIcon) {
      return (
        <Box className={cn('relative flex items-center w-full', className)}>
          {leftIcon && (
            <span className="absolute left-3 flex items-center justify-center text-(--patiya-color-muted-foreground) pointer-events-none">
              {leftIcon}
            </span>
          )}
          <input
            ref={internalInputRef}
            type={computedType}
            disabled={disabled}
            value={value}
            defaultValue={defaultValue}
            onChange={handleInputChange}
            className={cn(inputClassName, 'w-full')}
            {...props}
          />
          {computedRightIcon && (
            <span className="absolute right-3 flex items-center justify-center text-(--patiya-color-muted-foreground)">
              {computedRightIcon}
            </span>
          )}
        </Box>
      );
    }

    return (
      <input
        ref={internalInputRef}
        type={computedType}
        disabled={disabled}
        value={value}
        defaultValue={defaultValue}
        onChange={handleInputChange}
        className={inputClassName}
        {...props}
      />
    );
  }
);

