              className={cn(
                'inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border transition-all cursor-pointer',
                voted
                  ? 'bg-[var(--patiya-color-primary)] text-[var(--patiya-color-primary-foreground)] border-[var(--patiya-color-primary)]'
