      <Badge
        ref={ref}
        color={config.color}
        variant={variant}
        className={cn(
          'flex items-center gap-1.5 font-medium',
          iconOnly ? 'p-1.5 rounded-full aspect-square justify-center' : '',
          className
        )}
        {...props}
      >
        <span className="shrink-0">{config.icon}</span>
        {!iconOnly && <span>{label || config.label}</span>}
      </Badge>
    );
  }
);

