      ...props
    },
    ref
  ) => {
    const sizeClasses: Record<PatiyaSize, string> = {
      xs: 'h-7 text-xs px-2',
      sm: 'h-8 text-sm px-3',
      md: 'h-10 text-base px-4',
      lg: 'h-12 text-lg px-4',
      xl: 'h-14 text-xl px-5',
