      variantClasses[variant],
      invalid && 'border-[var(--patiya-color-destructive)] focus:border-[var(--patiya-color-destructive)] focus:ring-[var(--patiya-color-destructive)]/10',
      leftIcon ? 'pl-10 pr-10' : 'pr-10',
