"use client";
import React, { createContext, useContext, useState, useCallback } from 'react';
import { cn } from '../../utils/cn';
import { Box } from '../Layout/Box';

interface ToastOptions {
  id: string;
  title?: string;
  description?: string;
  type?: 'default' | 'success' | 'error' | 'warning' | 'info';
  duration?: number;
}

interface ToastContextType {
  toast: (options: Omit<ToastOptions, 'id'>) => void;
  dismiss: (id: string) => void;
}

const ToastContext = createContext<ToastContextType | null>(null);

export function ToastProvider({ children }: { children: React.ReactNode }) {
  const [toasts, setToasts] = useState<ToastOptions[]>([]);

  const toast = useCallback((options: Omit<ToastOptions, 'id'>) => {
    const id = Math.random().toString(36).substring(2, 9);
    setToasts((prev) => [...prev, { id, ...options }]);

    if (options.duration !== Infinity) {
      setTimeout(() => {
        setToasts((prev) => prev.filter((t) => t.id !== id));
      }, options.duration || 5000);
    }
  }, []);

  const dismiss = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  return (
    <ToastContext.Provider value={{ toast, dismiss }}>
      {children}
      <Box className="fixed bottom-0 right-0 z-[100] flex max-h-screen w-full flex-col-reverse p-4 sm:bottom-0 sm:right-0 sm:top-auto sm:flex-col md:max-w-[420px] gap-2 pointer-events-none">
        {toasts.map((t) => (
          <ToastItem key={t.id} toast={t} onDismiss={() => dismiss(t.id)} />
        ))}
      </Box>
    </ToastContext.Provider>
  );
}

export function useToast() {
  const context = useContext(ToastContext);
  if (!context) throw new Error('useToast must be used within ToastProvider');
  return context;
}

function ToastItem({ toast, onDismiss }: { toast: ToastOptions; onDismiss: () => void }) {
  const typeClasses = {
    default: 'bg-[var(--patiya-color-background)] border-[var(--patiya-color-border)] text-[var(--patiya-color-foreground)]',
    success: 'bg-[var(--patiya-color-success)] text-[var(--patiya-color-primary-foreground)] border-transparent',
    error: 'bg-[var(--patiya-color-destructive)] text-[var(--patiya-color-primary-foreground)] border-transparent',
    warning: 'bg-[var(--patiya-color-warning)] text-zinc-900 border-transparent',
    info: 'bg-[var(--patiya-color-info)] text-[var(--patiya-color-primary-foreground)] border-transparent',
  };

  return (
    <Box className={cn(
      "group pointer-events-auto relative flex w-full items-center justify-between space-x-4 overflow-hidden rounded-xl border p-5 shadow-lg transition-all animate-[pulse_0.2s_ease-out]",
      typeClasses[toast.type || 'default']
    )}>
      <Box className="flex w-full flex-col gap-1">
        {toast.title && <Box className="text-sm font-semibold leading-none tracking-tight">{toast.title}</Box>}
        {toast.description && <Box className="text-sm opacity-90 leading-relaxed mt-1">{toast.description}</Box>}
      </Box>
      <button 
        onClick={onDismiss} 
        className="absolute right-2 top-2 rounded-md p-1.5 opacity-0 transition-opacity group-hover:opacity-100 hover:bg-black/10 focus:opacity-100"
      >
        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
      </button>
    </Box>
  );
}

import React, { useState } from 'react';
import {
  useFloating,
  autoUpdate,
  offset,
  flip,
  shift,
  useHover,
  useFocus,
  useDismiss,
  useRole,
  useInteractions,
  FloatingPortal,
  Placement,
  useTransitionStyles
} from '@floating-ui/react';
import { cn } from '../../utils/cn';

export interface TooltipProps {
  content: React.ReactNode;
  children: React.ReactElement;
  placement?: Placement;
  className?: string;
  delay?: number;
}

export function Tooltip({ children, content, placement = 'top', className, delay = 0 }: TooltipProps) {
  const [isOpen, setIsOpen] = useState(false);

  const { refs, x, y, strategy, context } = useFloating({
    open: isOpen,
    onOpenChange: setIsOpen,
    placement,
    whileElementsMounted: autoUpdate,
    middleware: [
      offset(8),
      flip({
        fallbackAxisSideDirection: 'start',
      }),
      shift(),
    ],
  });

  const hover = useHover(context, { move: false, delay: { open: delay, close: 0 } });
  const focus = useFocus(context);
  const dismiss = useDismiss(context);
  const role = useRole(context, { role: 'tooltip' });

  const { getReferenceProps, getFloatingProps } = useInteractions([
    hover,
    focus,
    dismiss,
    role,
  ]);

  const { isMounted, styles } = useTransitionStyles(context, {
    duration: 150,
    initial: { opacity: 0, transform: 'scale(0.95)' },
  });

  return (
    <>
      {React.cloneElement(children as React.ReactElement<any> & React.RefAttributes<any>, {
        ref: refs.setReference,
        ...getReferenceProps(),
      })}
      {isMounted && (
        <FloatingPortal>
          <div
            ref={refs.setFloating}
            style={{ 
              position: strategy,
              top: y ?? 0,
              left: x ?? 0,
              width: 'max-content',
              ...styles 
            }}
            {...getFloatingProps()}
            className={cn(
              'z-50 px-3 py-1.5 text-xs font-medium rounded-md shadow-md',
              'bg-[var(--patiya-color-foreground)] text-[var(--patiya-color-background)]',
              className
            )}
          >
            {content}
          </div>
        </FloatingPortal>
      )}
    </>
  );
}

"use client";
import React, { forwardRef, createContext, useContext, useState } from 'react';
import { cn } from '../../utils/cn';

type TreeContextType = {
  expandedKeys: Set<string>;
  toggleExpanded: (key: string) => void;
  selectedKey?: string;
  selectKey: (key: string) => void;
  showGuides: boolean;
};

const TreeContext = createContext<TreeContextType>({
  expandedKeys: new Set(),
  toggleExpanded: () => {},
  selectedKey: undefined,
  selectKey: () => {},
  showGuides: true,
});

export type TreeViewProps = React.HTMLAttributes<HTMLDivElement> & {
  defaultExpandedKeys?: string[];
  selectedKey?: string;
  onSelect?: (key: string) => void;
  showGuides?: boolean;
};

export const TreeView = forwardRef<HTMLDivElement, TreeViewProps>(
  (
    {
      className,
      defaultExpandedKeys = [],
      selectedKey: controlledSelectedKey,
      onSelect,
      showGuides = true,
      children,
      ...props
    },
    ref
  ) => {
    const [expandedKeys, setExpandedKeys] = useState<Set<string>>(
      new Set(defaultExpandedKeys)
    );
    const [internalSelectedKey, setInternalSelectedKey] = useState<string | undefined>(
      undefined
    );

    const selectedKey = controlledSelectedKey !== undefined ? controlledSelectedKey : internalSelectedKey;

    const toggleExpanded = (key: string) => {
      setExpandedKeys((prev) => {
        const next = new Set(prev);
        if (next.has(key)) {
          next.delete(key);
        } else {
          next.add(key);
        }
        return next;
      });
    };

    const selectKey = (key: string) => {
      if (controlledSelectedKey === undefined) {
        setInternalSelectedKey(key);
      }
      onSelect?.(key);
    };

    return (
      <TreeContext.Provider
        value={{
          expandedKeys,
          toggleExpanded,
          selectedKey,
          selectKey,
          showGuides,
        }}
      >
        <div
          ref={ref}
          role="tree"
          className={cn('w-full text-sm font-sans select-none space-y-0.5', className)}
          {...props}
        >
          {children}
        </div>
      </TreeContext.Provider>
    );
  }
);
TreeView.displayName = 'TreeView';

export type TreeItemProps = React.HTMLAttributes<HTMLDivElement> & {
  id: string;
  label: React.ReactNode;
  icon?: React.ReactNode;
  badge?: React.ReactNode;
  children?: React.ReactNode;
  defaultExpanded?: boolean;
  disabled?: boolean;
};

export const TreeItem = forwardRef<HTMLDivElement, TreeItemProps>(
  (
    {
      className,
      id,
      label,
      icon,
      badge,
      children,
      defaultExpanded = false,
      disabled = false,
      ...props
    },
    ref
  ) => {
    const { expandedKeys, toggleExpanded, selectedKey, selectKey, showGuides } = useContext(TreeContext);

    const hasChildren = Boolean(children);
    const isExpanded = expandedKeys.has(id);
    const isSelected = selectedKey === id;

    const handleToggle = (e: React.MouseEvent) => {
      e.stopPropagation();
      if (disabled) return;
      if (hasChildren) {
        toggleExpanded(id);
      }
      selectKey(id);
    };

    return (
      <div
        ref={ref}
        role="treeitem"
        aria-expanded={hasChildren ? isExpanded : undefined}
        aria-selected={isSelected}
        className={cn('relative', className)}
        {...props}
      >
        <div
          onClick={handleToggle}
          className={cn(
            'group flex items-center gap-2 px-2.5 py-1.5 rounded-lg cursor-pointer text-sm transition-colors',
            disabled && 'opacity-50 cursor-not-allowed pointer-events-none',
            isSelected
              ? 'bg-[var(--patiya-color-primary)]/10 text-[var(--patiya-color-primary)] font-semibold'
              : 'text-[var(--patiya-color-foreground)] hover:bg-[var(--patiya-color-muted)]/60'
          )}
        >
          {hasChildren ? (
            <button
              type="button"
              tabIndex={-1}
              onClick={(e) => {
                e.stopPropagation();
                if (!disabled) toggleExpanded(id);
              }}
              className="w-4 h-4 flex items-center justify-center shrink-0 text-[var(--patiya-color-muted-foreground)] group-hover:text-[var(--patiya-color-foreground)] transition-colors"
            >
              <svg
                className={cn(
                  'w-3.5 h-3.5 transition-transform duration-300 ease-in-out',
                  isExpanded ? 'rotate-90' : 'rotate-0'
                )}
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <polyline points="9 18 15 12 9 6" />
              </svg>
            </button>
          ) : (
            <span className="w-4 h-4 shrink-0" />
          )}

          {icon && (
            <span
              className={cn(
                'shrink-0 text-[var(--patiya-color-muted-foreground)] transition-colors',
                isSelected && 'text-[var(--patiya-color-primary)]'
              )}
            >
              {icon}
            </span>
          )}

          <span className="truncate flex-1">{label}</span>

          {badge && <span className="ml-auto shrink-0">{badge}</span>}
        </div>

        {hasChildren && (
          <div
            className={cn(
              'grid transition-all duration-300 ease-in-out',
              isExpanded
                ? 'grid-rows-[1fr] opacity-100'
                : 'grid-rows-[0fr] opacity-0 pointer-events-none'
            )}
          >
            <div
              className={cn(
                'overflow-hidden transition-all duration-300 pl-6 ml-4 mt-0.5 space-y-0.5',
                showGuides && 'border-l border-[var(--patiya-color-border)]'
              )}
            >
              {children}
            </div>
          </div>
        )}
      </div>
    );
  }
);
TreeItem.displayName = 'TreeItem';

import React, { useState, useEffect } from 'react';
import { cn } from '../../utils/cn';

export interface TypewriterTextProps extends React.HTMLAttributes<HTMLSpanElement> {
  text: string;
  speed?: number;
  delay?: number;
  cursor?: boolean;
  onComplete?: () => void;
  as?: React.ElementType;
}

export const TypewriterText = React.forwardRef<HTMLElement, TypewriterTextProps>(
  ({ className, text, speed = 30, delay = 0, cursor = true, onComplete, as: Component = 'span', ...props }, ref) => {
    const [displayedText, setDisplayedText] = useState('');
    const [isComplete, setIsComplete] = useState(false);
    const [isStarted, setIsStarted] = useState(false);

    useEffect(() => {
      // Reset state if text changes
      setDisplayedText('');
      setIsComplete(false);
      setIsStarted(false);

      const startTimeout = setTimeout(() => {
        setIsStarted(true);
      }, delay);

      return () => clearTimeout(startTimeout);
    }, [text, delay]);

    useEffect(() => {
      if (!isStarted) return;

      let currentIndex = 0;
      let interval: ReturnType<typeof setInterval>;

      const typeNextChar = () => {
        if (currentIndex < text.length) {
          setDisplayedText((prev) => prev + text.charAt(currentIndex));
          currentIndex++;
        } else {
          clearInterval(interval);
          setIsComplete(true);
          onComplete?.();
        }
      };

      interval = setInterval(typeNextChar, speed);

      return () => clearInterval(interval);
    }, [isStarted, text, speed, onComplete]);

    return (
      <Component ref={ref} className={cn("inline-block", className)} {...props}>
        {displayedText}
        {cursor && (!isComplete || isStarted) && (
          <span 
            className={cn(
              "inline-block w-1.5 h-[1em] ml-0.5 align-middle bg-[var(--patiya-color-primary)]",
              isComplete ? "animate-pulse opacity-0 duration-1000" : "animate-pulse opacity-100"
            )}
          />
        )}
      </Component>
    );
  }
);

TypewriterText.displayName = 'TypewriterText';

